import base64,hashlib,json,os,subprocess
from pathlib import Path
root=Path('/home/root/aura-sface-live-configcheck-20261021/49fdc0b23fd30eff')
p=root/'board/identity/model_store.py'
new=base64.b64decode('')
assert hashlib.sha256(new).hexdigest()=='310b4f3290fdf9d07b47800477e8ceb4c7631fbb9e622fac0f8c547a0d1563da'
old=p.read_bytes();oldsha=hashlib.sha256(old).hexdigest()
assert oldsha in ('5d6cd6fe6ddbff9b236b8d09791d7f013f3d02815c8bde99ae913cc7bc2180f0','310b4f3290fdf9d07b47800477e8ceb4c7631fbb9e622fac0f8c547a0d1563da')
backup=p.with_name(p.name+'.before-symlink-guard')
if oldsha!='310b4f3290fdf9d07b47800477e8ceb4c7631fbb9e622fac0f8c547a0d1563da':
 if backup.exists():assert backup.read_bytes()==old
 else:backup.write_bytes(old)
 temp=p.with_name(p.name+'.new');temp.write_bytes(new);os.replace(str(temp),str(p))
fallback=Path('/home/root/aura-handsfree-dialogue-20261020/candidate-0c0a8ab46ec2/camera_live_config/board_identity.json')
original=fallback.read_bytes()
cfg=root/'TEST_ONLY_NULL_THRESHOLDS.json';c=json.loads(cfg.read_text());assert c['threshold'] is None and c['ambiguity_margin'] is None
assert not Path(c['database']).exists()
r=subprocess.run(['/usr/bin/python3','-B',str(root/'tools/check_dpu_identity_config.py'),'--config',str(cfg)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=12)
assert r.returncode==0,r.stderr.decode()[-1500:]
v=json.loads(r.stdout);assert not v['runner_created'] and not v['database_created']
assert fallback.read_bytes()==original and not Path(c['database']).exists()
print(json.dumps({'check':v,'source_hashes':{'tools/check_dpu_identity_config.py':hashlib.sha256((root/'tools/check_dpu_identity_config.py').read_bytes()).hexdigest(),'board/identity/model_store.py':hashlib.sha256(p.read_bytes()).hexdigest()},'original_config_unchanged':True,'new_database_created':False,'thresholds_null':True,'production_backend_changed':False,'latest_symlink_guard_board_rechecked':True,'root':str(root)}))
